//! Error type for the gemini-powerbox-adv3-driver.
//!
//! The hub's failure modes are the shared transport-driver common core plus
//! the device-specific variants below. The enum, its ASCOM classification,
//! `From<TransportError>`, and the `Result` alias are all generated by
//! [`rusty_photon_driver::driver_error!`]. The codec-layer
//! `From<SessionError<GeminiCodecError>>` lives in [`crate::codec`] and
//! targets this (local) enum.
//!
//! `DewModeGate` maps to `NOT_IMPLEMENTED`, not `INVALID_OPERATION`: ASCOM
//! ties the Switch write path to `CanWrite`, and a dew row that is read-only
//! in the channel's current mode already reports `CanWrite = false`, so the
//! write has to answer `MethodNotImplemented` for the two to agree. The
//! message names the mode switch to change first.
//!
//! The connect refusals — `WrongModel`, `FirmwareTooOld`, `NoIdentity` —
//! and an unconfirmed write carry no `ascom` arm: the macro's fallthrough
//! maps them to `INVALID_OPERATION`, which is what each means to a client.

rusty_photon_driver::driver_error! {
    /// Errors that can occur when interacting with the Advanced 3.
    pub enum GeminiError {
        #[error("invalid switch ID: {0}")]
        InvalidSwitchId(usize),
        #[error("switch not writable: {0}")]
        SwitchNotWritable(usize),
        #[error(
            "switch {switch_id} ({name}) is read-only while {channel} is in {mode} mode; \
             change {mode_switch} first"
        )]
        DewModeGate {
            switch_id: usize,
            name: String,
            channel: &'static str,
            mode: &'static str,
            mode_switch: String,
        },
        #[error("{channel} cannot enter Auto mode: the {sensor} is not attached")]
        AutoNeedsSensor {
            channel: &'static str,
            sensor: &'static str,
        },
        #[error("write to {name} not confirmed: asked for {asked}, the hub reports {reported}")]
        WriteNotConfirmed {
            name: String,
            asked: f64,
            reported: f64,
        },
        #[error("{0}")]
        WrongModel(String),
        #[error(
            "firmware {got} is older than {min}, the oldest whose frame this driver knows; \
             upgrade it with the vendor's FirmwareUpgradeTool"
        )]
        FirmwareTooOld { got: String, min: String },
        #[error("no Gemini identity reply on {port}")]
        NoIdentity { port: String },
    }
    ascom {
        Self::InvalidSwitchId(_) => INVALID_VALUE,
        Self::SwitchNotWritable(_) => NOT_IMPLEMENTED,
        Self::DewModeGate { .. } => NOT_IMPLEMENTED,
    }
}

#[cfg(test)]
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use super::*;
    use ascom_alpaca::ASCOMErrorCode;

    #[test]
    fn a_mode_gated_write_is_not_implemented_so_it_agrees_with_can_write() {
        let err = GeminiError::DewModeGate {
            switch_id: 13,
            name: "DEW6 Enabled".to_string(),
            channel: "DEW6",
            mode: "Manual",
            mode_switch: "DEW6 Mode".to_string(),
        };
        let ascom = err.to_ascom_error();
        assert_eq!(ascom.code, ASCOMErrorCode::NOT_IMPLEMENTED);
        assert!(ascom.message.contains("DEW6 Mode"), "{}", ascom.message);
    }

    #[test]
    fn the_connect_refusals_and_an_unconfirmed_write_are_invalid_operation() {
        for err in [
            GeminiError::WrongModel("x".to_string()),
            GeminiError::FirmwareTooOld {
                got: "3.0.7".to_string(),
                min: "3.0.8".to_string(),
            },
            GeminiError::NoIdentity {
                port: "/dev/ttyUSB0".to_string(),
            },
            GeminiError::WriteNotConfirmed {
                name: "DC3".to_string(),
                asked: 1.0,
                reported: 0.0,
            },
            GeminiError::AutoNeedsSensor {
                channel: "DEW6",
                sensor: "DS18B20 lens probe",
            },
        ] {
            assert_eq!(
                err.to_ascom_error().code,
                ASCOMErrorCode::INVALID_OPERATION,
                "{err}"
            );
        }
    }

    #[test]
    fn an_unconfirmed_write_names_the_switch_and_both_values() {
        let text = GeminiError::WriteNotConfirmed {
            name: "DC3".to_string(),
            asked: 1.0,
            reported: 0.0,
        }
        .to_string();
        assert!(text.contains("DC3"), "{text}");
        assert!(text.contains("asked for 1"), "{text}");
        assert!(text.contains("reports 0"), "{text}");
    }
}
